const websitePostCounts = `-- name: WebsitePostCounts :many
SELECT p.kind, p.status, p.web_on, p.publish_mode, p.visibility, coalesce(c.status, '')::text AS campaign_status, count(*)::bigint AS n
FROM website_posts p LEFT JOIN campaigns c ON c.id = p.campaign_id
WHERE p.workspace_id = $1 AND p.deleted_at IS NULL
GROUP BY p.kind, p.status, p.web_on, p.publish_mode, p.visibility, c.status
`

type WebsitePostCountsRow struct {
	Kind           string `json:"kind"`
	Status         string `json:"status"`
	WebOn          bool   `json:"webOn"`
	PublishMode    string `json:"publishMode"`
	Visibility     string `json:"visibility"`
	CampaignStatus string `json:"campaignStatus"`
	N              int64  `json:"n"`
}

// Posts by kind, status and visibility; a campaign's post set to go live
// with a scheduled send counts as scheduled.
func (q *Queries) WebsitePostCounts(ctx context.Context, workspaceID uuid.UUID) ([]WebsitePostCountsRow, error) {
	rows, err := q.db.Query(ctx, websitePostCounts, workspaceID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []WebsitePostCountsRow{}
	for rows.Next() {
		var i WebsitePostCountsRow
		if err := rows.Scan(
			&i.Kind,
			&i.Status,
			&i.WebOn,
			&i.PublishMode,
			&i.Visibility,
			&i.CampaignStatus,
			&i.N,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

