const websiteSentWithoutPost = `-- name: WebsiteSentWithoutPost :many
SELECT c.id, c.name, c.subject, c.preheader, c.audience, coalesce(c.audience_count, 0)::bigint AS recipients,
       coalesce(c.started_at, c.completed_at, c.created_at)::timestamptz AS sent_at,
       coalesce(ai.hidden, false)::boolean AS archive_hidden, (ai.campaign_id IS NOT NULL)::boolean AS archived
FROM campaigns c
LEFT JOIN archive_issues ai ON ai.campaign_id = c.id
WHERE c.workspace_id = $1 AND c.status = 'sent' AND c.deleted_at IS NULL AND coalesce(c.digest_role, '') IN ('', 'issue')
  AND NOT EXISTS (SELECT 1 FROM website_posts p WHERE p.campaign_id = c.id AND p.deleted_at IS NULL AND (p.web_on OR p.status <> 'draft'))
ORDER BY sent_at DESC, c.id DESC
LIMIT 100
`

type WebsiteSentWithoutPostRow struct {
	ID            uuid.UUID       `json:"id"`
	Name          string          `json:"name"`
	Subject       string          `json:"subject"`
	Preheader     string          `json:"preheader"`
	Audience      json.RawMessage `json:"audience"`
	Recipients    int64           `json:"recipients"`
	SentAt        time.Time       `json:"sentAt"`
	ArchiveHidden bool            `json:"archiveHidden"`
	Archived      bool            `json:"archived"`
}

// Sent campaigns that aren't posts yet ("Publish past campaigns").
func (q *Queries) WebsiteSentWithoutPost(ctx context.Context, workspaceID uuid.UUID) ([]WebsiteSentWithoutPostRow, error) {
	rows, err := q.db.Query(ctx, websiteSentWithoutPost, workspaceID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []WebsiteSentWithoutPostRow{}
	for rows.Next() {
		var i WebsiteSentWithoutPostRow
		if err := rows.Scan(
			&i.ID,
			&i.Name,
			&i.Subject,
			&i.Preheader,
			&i.Audience,
			&i.Recipients,
			&i.SentAt,
			&i.ArchiveHidden,
			&i.Archived,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

