const websiteTags = `-- name: WebsiteTags :many

SELECT t.id, t.workspace_id, t.name, t.slug, t.description, t.list_id, t.created_by, t.created_at, t.updated_at,
       count(p.id) FILTER (WHERE p.status = 'published')::bigint AS published,
       count(p.id) FILTER (WHERE p.status = 'unpublished')::bigint AS unpublished
FROM website_tags t
LEFT JOIN website_post_tags pt ON pt.tag_id = t.id
LEFT JOIN website_posts p ON p.id = pt.post_id AND p.deleted_at IS NULL
WHERE t.workspace_id = $1
GROUP BY t.id
ORDER BY t.created_at, t.name
`

type WebsiteTagsRow struct {
	ID          uuid.UUID  `json:"id"`
	WorkspaceID uuid.UUID  `json:"workspaceId"`
	Name        string     `json:"name"`
	Slug        string     `json:"slug"`
	Description string     `json:"description"`
	ListID      *uuid.UUID `json:"listId"`
	CreatedBy   *uuid.UUID `json:"createdBy"`
	CreatedAt   time.Time  `json:"createdAt"`
	UpdatedAt   time.Time  `json:"updatedAt"`
	Published   int64      `json:"published"`
	Unpublished int64      `json:"unpublished"`
}

// Tags
// Every tag with its published posts (and whether only unpublished ones are left).
func (q *Queries) WebsiteTags(ctx context.Context, workspaceID uuid.UUID) ([]WebsiteTagsRow, error) {
	rows, err := q.db.Query(ctx, websiteTags, workspaceID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []WebsiteTagsRow{}
	for rows.Next() {
		var i WebsiteTagsRow
		if err := rows.Scan(
			&i.ID,
			&i.WorkspaceID,
			&i.Name,
			&i.Slug,
			&i.Description,
			&i.ListID,
			&i.CreatedBy,
			&i.CreatedAt,
			&i.UpdatedAt,
			&i.Published,
			&i.Unpublished,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

